public static void check(Solution solution) {
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,3,2,3,1,4,3,2}, new int[]{1,-1,1,-1}), 2);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,2,2,3,4,5}, new int[]{1,0,1}), 1);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,4,4,1,3,5,5,3}, new int[]{1,0,-1}), 2);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{5,5,5,5,5,5}, new int[]{0,0,0}), 3);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,2,2,3,4}, new int[]{1,0,1}), 1);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,2,2,3,3,4}, new int[]{1,0,1,0}), 1);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,2,3,4,5,6}, new int[]{1,1}), 4);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,1,1,1,1}, new int[]{0,0,0}), 2);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{5,4,3,2,1}, new int[]{-1,-1,-1}), 2);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,3,2,3,4,5}, new int[]{1,-1,1}), 1);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,1,1,1,1}, new int[]{0,0}), 3);
    assert Arrays.equals(solution.countMatchingSubarrays(new int[]{1,2,2,3,3,4,4,5}, new int[]{1,0,0,1,0,0}), 0);
